// Promise-based asset loaders (ported from raster). Queue them in a scene's
// `preload(load)` hook — the boot waits (showing the loading screen) before
// calling `setup()`. Audio loads through `this.sound.load(url)`. Every loader
// caches by URL: re-requesting a loaded asset costs nothing.

interface ImageEntry {
  img: HTMLImageElement;
  ok: boolean;
  settled: boolean;
  promise: Promise<HTMLImageElement>;
}

const imageCache = new Map<string, ImageEntry>();

/** `true` once `url` has finished loading (or failing) via `loadImage`. */
export function isImageCached(url: string): boolean {
  return imageCache.get(url)?.settled ?? false;
}

// Model DATA (parsed geometry + decoded textures) is cached in the lazy 3D
// chunk by `loadModelData`, but the preload queue lives in the main bundle and
// must decide whether a model still needs loading WITHOUT pulling that chunk in
// — so the set of loaded model keys is mirrored here.
const loadedModels = new Set<string>();

/** `true` once model DATA for `url` has been loaded + cached (via the 3D chunk's `loadModelData`). */
export function isModelCached(url: string): boolean {
  return loadedModels.has(url);
}

/** @internal Mark model DATA for `url` as cached — called by `loadModelData` in the 3D chunk. */
export function markModelLoaded(url: string): void {
  loadedModels.add(url);
}

/** The decoded image for `url`, or `null` if it hasn't loaded (or failed). Sync — preload first. */
export function getImage(url: string): HTMLImageElement | null {
  const e = imageCache.get(url);
  return e && e.settled && e.ok ? e.img : null;
}

/**
 * Load an image and resolve when it is decoded (or has failed — the promise
 * never rejects, so a missing file can't wedge a loading bar). Cached by URL.
 */
export function loadImage(url: string): Promise<HTMLImageElement> {
  const hit = imageCache.get(url);
  if (hit) return hit.promise;
  if (typeof Image === 'undefined') {
    // Headless — settle immediately as a failed load.
    const entry: ImageEntry = { img: null as unknown as HTMLImageElement, ok: false, settled: true, promise: Promise.resolve(null as unknown as HTMLImageElement) };
    imageCache.set(url, entry);
    return entry.promise;
  }
  const img = new Image();
  // Request cross-origin images anonymously so any canvas/GPU texture they feed
  // stays UNTAINTED. Remote art (generated sprites/logos/backgrounds on the CDN)
  // is cross-origin; without this the browser marks the decoded image as
  // cross-origin-tainted and copyExternalImageToTexture throws SecurityError
  // ("The external image is tainted by cross-origin data"). Must be set BEFORE
  // src. Harmless for same-origin / data: images. Requires the host to send CORS
  // headers (the CDN does). Mirrors engine/raster texture.ts.
  img.crossOrigin = 'anonymous';
  img.src = url;
  const entry: ImageEntry = {
    img, ok: false, settled: false,
    promise: img.decode().then(
      () => { entry.ok = true; entry.settled = true; return img; },
      () => { entry.settled = true; return img; },
    ),
  };
  imageCache.set(url, entry);
  return entry.promise;
}

const textCache = new Map<string, string>();

/** `true` if `url` has already been fetched by `loadText`/`loadJson` (cached) — so re-queuing it needs no load. */
export function isTextCached(url: string): boolean {
  return textCache.has(url);
}

/**
 * Load a plain-text file (CSV, TSV, level data, etc.) from `url` and return
 * its content as a string. Results are cached by URL.
 * Returns `''` on network error or in headless (non-browser) environments.
 */
export async function loadText(url: string): Promise<string> {
  const hit = textCache.get(url);
  if (hit !== undefined) return hit;
  if (typeof fetch === 'undefined') return ''; // headless — no-op
  try {
    const t = await (await fetch(url)).text();
    textCache.set(url, t);
    return t;
  } catch {
    return '';
  }
}

/**
 * Load and parse a JSON file from `url` (level data, config).
 * Delegates to `loadText` for caching and error handling.
 * Returns `null` on error or empty response.
 */
export async function loadJson<T = unknown>(url: string): Promise<T> {
  const t = await loadText(url);
  return (t ? JSON.parse(t) : null) as T;
}

const binaryCache = new Map<string, ArrayBuffer>();

/** `true` if `url` has already been fetched by `loadBinary` (cached) — so re-queuing it needs no load. */
export function isBinaryCached(url: string): boolean {
  return binaryCache.has(url);
}

/**
 * Load a binary file (packed level data, a model) from `url` as an
 * `ArrayBuffer`. Cached by URL — queue with `load.binary(url)` in `preload`,
 * read back instantly here in `setup`. Retries once, then THROWS with the
 * URL in the message — a swallowed failure used to surface downstream as
 * "GLB: truncated header — 0 bytes", which named neither cause nor file.
 * Headless (non-browser) environments still get an empty buffer.
 */
export async function loadBinary(url: string): Promise<ArrayBuffer> {
  const hit = binaryCache.get(url);
  if (hit !== undefined) return hit;
  if (typeof fetch === 'undefined') return new ArrayBuffer(0); // headless — no-op
  let lastErr: unknown = 'empty response';
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const resp = await fetch(url);
      if (!resp.ok) { lastErr = `HTTP ${resp.status}`; continue; }
      const b = await resp.arrayBuffer();
      if (b.byteLength > 0) {
        binaryCache.set(url, b);        // only real bytes are cached
        return b;
      }
    } catch (e) {
      lastErr = e;
    }
  }
  throw new Error(`loadBinary: '${url}' failed after retry (${String(lastErr)})`);
}

// Lazily-loaded subsystems (the 3D chunk's model-data cache) register a clearer
// here so `clearAssetCaches()` can flush them WITHOUT the main bundle importing
// the chunk — only chunks that actually loaded ever register.
// ── Web fonts ────────────────────────────────────────────────────────────────
// A bitmap font BAKES its glyphs with the browser's current face for the CSS
// font string. If the real face hasn't arrived yet the browser silently
// substitutes a fallback (the "why is my title in Arial?" bug) and those wrong
// glyphs are what land on the atlas — permanently, because baking is
// idempotent. So a web font is an ASSET like any other: queue it with
// `load.font(family, url)` and it is loaded, registered on `document.fonts`
// and AWAITED before setup() bakes anything.

const fontCache = new Map<string, Promise<boolean>>();
const fontsReady = new Set<string>();

/** `true` once the family loaded via `loadFont` is registered and usable. */
export function isFontCached(family: string): boolean {
  return fontsReady.has(family);
}

/** `true` if the browser can render `cssFont` (e.g. '32px Orbitron') right now. */
export function isFontUsable(cssFont: string): boolean {
  const fonts = typeof document !== 'undefined' ? document.fonts : undefined;
  if (!fonts?.check) return true;   // no Font Loading API — nothing to wait for
  try { return fonts.check(cssFont); } catch { return true; } // malformed shorthand: not our call to police
}

/**
 * Load a web font file (woff2 / woff / ttf / otf) and register it on the
 * document under `family`, so `game.assets.font({ font: '32px ' + family })`
 * bakes the REAL face. Cached by family|url; never rejects (a failed font
 * resolves `false` and the browser's fallback is used) so a bad URL can't
 * wedge the loading bar.
 */
export function loadFont(family: string, url: string, descriptors?: FontFaceDescriptors): Promise<boolean> {
  const key = `${family}|${url}`;
  const hit = fontCache.get(key);
  if (hit) return hit;
  const unsupported = typeof FontFace === 'undefined' || typeof document === 'undefined' || !document.fonts;
  const p: Promise<boolean> = unsupported
    ? Promise.resolve(false)                        // headless — nothing to load into
    : new FontFace(family, `url(${url})`, descriptors).load().then(
        (face) => { document.fonts.add(face); fontsReady.add(family); return true; },
        (err) => { console.warn(`Phaser AE: web font '${family}' failed to load from ${url} —`, err); return false; },
      );
  fontCache.set(key, p);
  return p;
}

/**
 * Resolve once every font the document has STARTED loading has settled. Catches
 * faces declared with CSS `@font-face` in the host page (which `load.font()`
 * knows nothing about). Cheap and always safe — resolves immediately when
 * nothing is pending.
 */
export function fontsSettled(): Promise<void> {
  const fonts = typeof document !== 'undefined' ? document.fonts : undefined;
  return fonts?.ready ? fonts.ready.then(() => undefined, () => undefined) : Promise.resolve();
}

const cacheClearers = new Set<() => void>();

/** @internal Register a cache-flush callback, run by `clearAssetCaches()`. */
export function registerCacheClearer(fn: () => void): void {
  cacheClearers.add(fn);
}

/**
 * Drop every cached asset (images, text/JSON, binaries, model data) so the
 * memory can be reclaimed — called by `Game.destroy()`. NOTE: these caches are
 * module-global (shared across Game instances on a page), so this frees assets
 * for ALL games; only relevant if you run more than one at once.
 */
export function clearAssetCaches(): void {
  imageCache.clear();
  textCache.clear();
  binaryCache.clear();
  loadedModels.clear();
  // Web fonts are deliberately NOT cleared: the FontFace stays registered on
  // document.fonts, so dropping our record would only re-download it.
  for (const fn of cacheClearers) fn();
}
