const registry = new Map<string, VfxDef>(Object.entries({ ...VFX, ...VFX_PACK }).map(([, d]) => [d.name, d]));

/** Register a custom VfxDef (or override) by name — the block path. */
export function registerVfx(def: VfxDef): void {
  registry.set(def.name, def);
}

/** Resolve a name (or pass a def through) against the registry — shared by
 * the 2D VfxSystem and the 3D world.trail() path. */
export function resolveVfx(v: string | VfxDef): VfxDef {
  const def = typeof v === 'string' ? registry.get(v) : v;
  if (!def) throw new Error(`unknown vfx '${String(v)}' — registered: ${[...registry.keys()].join(', ')}`);
  return def;
}

const resolve = resolveVfx;

// ── Trails ───────────────────────────────────────────────────────────────────

interface TrailPoint { x: number; y: number; age: number }

/** A live trail — feed `point(x, y)` every frame (or bind a sprite via sprite.vfx). */
export class TrailEmitter {
  /** @internal */ points: TrailPoint[] = [];
  /** @internal */ dead = false;
  /** @internal Wired by VfxSystem — the shed target for `sparks`. */
  fx: Particles | null = null;
  private readonly t: Required<Omit<NonNullable<VfxDef['trail']>, 'sparks'>>;
  private readonly sparks: TrailSparks | null;
  // Arc-spaced shedding state: the last fed head + travel toward the next shed.
  private hx = 0;
  private hy = 0;
  private hasHead = false;
  private shedAcc = 0;

  /** @internal */
  constructor(def: VfxDef) {
    const t = def.trail ?? {};
    this.t = {
      width: t.width ?? 8, life: t.life ?? 0.5, colors: t.colors ?? ['#ffffff'],
      add: t.add ?? false, taper: t.taper ?? true, alpha: t.alpha ?? 0.8,
      spacing: t.spacing ?? 3,
      // 3D-only knobs — carried for the type, unused by the 2D ribbon.
      turbulence: t.turbulence ?? 0.35, erode: t.erode ?? 0.55, core: t.core ?? 0.5,
      fiber: t.fiber ?? 1, hard: t.hard ?? 0, crackle: t.crackle ?? 0,
      facing: t.facing ?? 'view',
    };
    this.sparks = t.sparks ?? null;
  }

  /** Record the head position for this frame. */
  point(x: number, y: number): void {
    // Sparks shed ARC-SPACED along the swept path (never per frame): every
    // 1/per world units of travel drops one at the exact crossing point.
    if (this.sparks && this.fx && this.hasHead) {
      const s = this.sparks;
      const step = 1 / (s.per ?? 0.25);
      let dx = x - this.hx, dy = y - this.hy;
      const seg = Math.hypot(dx, dy);
      if (seg > 0) {
        dx /= seg; dy /= seg;
        let travelled = this.shedAcc + seg;
        let along = 0;
        while (travelled >= step) {
          travelled -= step;
          along = seg - travelled;
          this.fx.emit({
            x: this.hx + dx * along, y: this.hy + dy * along, count: 1,
            speed: s.speed ?? 30, speedVar: (s.speed ?? 30) * 0.5,
            life: s.life ?? 0.45, lifeVar: (s.life ?? 0.45) * 0.3,
            size: s.size ?? 2, sizeVar: (s.size ?? 2) * 0.4,
            colors: s.ramp ? undefined : (s.colors ?? this.t.colors),
            ramp: s.ramp,
            add: s.add ?? this.t.add,
            gravity: s.gravity ?? 0,
            drag: s.drag ?? 1.5,
            twinkle: s.twinkle ?? 0.6,
          });
        }
        this.shedAcc = travelled;
      }
    }
    this.hx = x; this.hy = y; this.hasHead = true;
    const head = this.points[this.points.length - 1];
    if (head && Math.hypot(x - head.x, y - head.y) < this.t.spacing) return;
    this.points.push({ x, y, age: 0 });
  }

  /** Stop feeding and let the ribbon fade out, then auto-remove. */
  release(): void {
    this.dead = true;
  }

  /** @internal Age + expire points. Returns true while anything remains. */
  update(dt: number): boolean {
    const life = this.t.life;
    for (const p of this.points) p.age += dt;
    while (this.points.length && this.points[0].age >= life) this.points.shift();
    return this.points.length > 0 || !this.dead;
  }

  /** @internal Push the ribbon as fading segments (head→tail gradient). */
  draw(d: Draw): void {
    const pts = this.points;
    const { width, life, colors, add, taper, alpha } = this.t;
    for (let i = 1; i < pts.length; i++) {
      const a = pts[i - 1], b = pts[i];
      const k = 1 - b.age / life;                    // 1 head → 0 tail
      if (k <= 0) continue;
      const w = width * (taper ? k : 1);
      const ci = (1 - k) * (colors.length - 1);
      const color = colors[Math.min(colors.length - 1, Math.round(ci))];
      d.trailSegment(a.x, a.y, b.x, b.y, Math.max(0.5, w), color, alpha * k, add);
    }
  }
}

// ── Bursts ───────────────────────────────────────────────────────────────────

interface LiveBurst {
  def: VfxDef;
  x: number; y: number; angle: number;
  age: number;
  fired: boolean[];
}

// ── The per-scene system ─────────────────────────────────────────────────────

/**
 * The scene's VFX system: continuous trails + one-shot bursts, all data.
 * Trails draw UNDER the sprites (streams behind the body); burst rings and
 * flashes draw OVER them; burst particle layers ride the particle system.
 */
export class VfxSystem {
  private trails = new Set<TrailEmitter>();
  private bound = new Map<Sprite, TrailEmitter>();
  private bursts: LiveBurst[] = [];

  /** @internal Wired by the Scene: the game's particle system. */
  particles: Particles | null = null;

  /** Start a trail you feed yourself: `const t = scene.vfx.trail('flameTrail'); t.point(x, y)`. */
  trail(vfx: string | VfxDef): TrailEmitter {
    const t = new TrailEmitter(resolve(vfx));
    t.fx = this.particles;           // sparks shed into the game's particles
    this.trails.add(t);
    return t;
  }

  /** Trigger a one-shot burst recipe at a point. `angle` rotates directional emits (radians). */
  burst(vfx: string | VfxDef, x: number, y: number, opts?: { angle?: number }): void {
    const def = resolve(vfx);
    if (!def.burst?.length) return;
    this.bursts.push({ def, x, y, angle: opts?.angle ?? 0, age: 0, fired: def.burst.map(() => false) });
  }

  /** @internal Feed a sprite's auto-trail (creates it on first sight). */
  feed(sprite: Sprite, vfx: string | VfxDef): void {
    let t = this.bound.get(sprite);
    if (!t) {
      t = this.trail(vfx);
      this.bound.set(sprite, t);
    }
    t.point(sprite.centerX, sprite.centerY);
  }

  /** @internal Per-frame tick (scene.update). */
  update(dt: number): void {
    for (const t of this.trails) {
      if (!t.update(dt)) this.trails.delete(t);
    }
    for (const [s, t] of this.bound) {
      if (s.dead || !s.vfx) {
        t.release();                 // ribbon fades out after the sprite dies
        this.bound.delete(s);
      }
    }
    for (let i = this.bursts.length - 1; i >= 0; i--) {
      const b = this.bursts[i];
      b.age += dt;
      let done = true;
      b.def.burst!.forEach((layer, li) => {
        const delay = layer.delay ?? 0;
        if (!b.fired[li] && b.age >= delay) {
          b.fired[li] = true;
          if (layer.emit && this.particles) {
            this.particles.emit({ ...layer.emit, x: b.x, y: b.y, angle: (layer.emit.angle ?? 0) + b.angle });
          }
        }
        const t = layer.ring?.time ?? layer.flash?.time ?? 0;
        if (b.age < delay + t) done = false;
        if (!b.fired[li]) done = false;
      });
      if (done) this.bursts.splice(i, 1);
    }
  }

  /** @internal Trails, drawn BEFORE the sprites (the ribbon streams behind). */
  drawUnder(d: Draw): void {
    for (const t of this.trails) t.draw(d);
  }

  /** @internal Rings + flashes, drawn OVER the sprites. */
  drawOver(d: Draw): void {
    for (const b of this.bursts) {
      b.def.burst!.forEach((layer, li) => {
        const delay = layer.delay ?? 0;
        const local = b.age - delay;
        if (local < 0 || !b.fired[li]) return;
        if (layer.ring) {
          const r = layer.ring;
          const k = Math.min(1, local / r.time);
          if (k < 1) {
            const radius = (r.from ?? 6) + ((r.to - (r.from ?? 6)) * k);
            d.ring(b.x, b.y, radius, (r.width ?? 3) * (1 - k * 0.6), r.color ?? '#ffffff', (1 - k) * (r.add ? 1 : 0.8));
          }
        }
        if (layer.flash) {
          const f = layer.flash;
          const k = Math.min(1, local / f.time);
          if (k < 1) d.circle(b.x, b.y, f.radius * (0.6 + 0.4 * k), f.color ?? '#ffffff', (1 - k) * 0.9);
        }
      });
    }
  }

  /** @internal Everything stops with the scene (transitions drop the system). */
  clear(): void {
    this.trails.clear();
    this.bound.clear();
    this.bursts = [];
  }
}
