// Particles: CPU-simulated, fully pooled, drawn as SDF discs or sprite frames
// through the frame's batches — normal alpha or ADDITIVE (light accumulates:
// fire, sparks, magic — the eye-candy default). At v2's budgets tens of
// thousands are cheap; compute-driven particles are a later ceiling-raiser.
//
// You never manage instances: emit() a burst (or call it every frame for a
// stream) and the system ages, moves, fades and recycles everything.
// Module load is DOM/GPU-free — the sim is headlessly testable (pass a
// seeded rng to the constructor for deterministic tests).

import type { Draw } from './draw.js';
import { rgba, type Rgba } from './color.js';

/** Built-in colour ramp for `EmitOptions.ramp`. The particle walks the stops
 * from birth to death. Explosions (fire/ember/spark), atmosphere (smoke,
 * toxic), magic effects (magic, ice), or a full-spectrum rainbow. */
export type RampName = 'fire' | 'spark' | 'ember' | 'smoke' | 'ice' | 'magic' | 'toxic' | 'rainbow';

/** The named life-ramps (head = birth, last stop = death). */
export const RAMPS: Record<RampName, string[]> = {
  fire: ['#fff7e0', '#ffd23f', '#ff8c00', '#ff2d00', '#5c0a00'],
  spark: ['#ffffff', '#fff0a8', '#ffae00', '#ff6a00'],
  ember: ['#ffd166', '#ff7b00', '#c81e00', '#360a00'],
  smoke: ['#d7dde0', '#9aa4aa', '#5a6066', '#2b2f33'],
  ice: ['#ffffff', '#b3ecff', '#33a1ff', '#0a2a66'],
  magic: ['#ffffff', '#ff9bf2', '#b14dff', '#3d0a66'],
  toxic: ['#f0ffd0', '#b6f000', '#5aa800', '#143d00'],
  rainbow: ['#ff2d55', '#ff9500', '#ffea00', '#34c759', '#00c7ff', '#af52de'],
};

/** Resolve a ramp (named or custom hex stops) to parsed colours. */
export function resolveRamp(ramp: RampName | string[]): Rgba[] {
  const stops = Array.isArray(ramp) ? ramp : RAMPS[ramp];
  return (stops ?? ['#ffffff']).map((c) => rgba(c));
}

export interface EmitOptions {
  x: number;
  y: number;
  /** Particles in this burst (default 12). */
  count?: number;
  /** Initial speed ± speedVar, world units/s (default 90 ± 40). speedVar: 0 = a clean ring. */
  speed?: number;
  speedVar?: number;
  /** Emission direction (radians, clockwise; default 0) ± spread/2 (default: full circle). */
  angle?: number;
  spread?: number;
  /** Distribute angles EVENLY across the spread instead of randomly — a clean ring or fan. */
  even?: boolean;
  /** Jitter the spawn point within this radius (spread origin). Default 0 = point. */
  spawnRadius?: number;
  /** Lifetime seconds ± lifeVar (default 0.7 ± 0.3). */
  life?: number;
  lifeVar?: number;
  /** Disc radius / frame half-size ± sizeVar (default 4 ± 2). */
  size?: number;
  sizeVar?: number;
  /** Size over life: true = shrink to nothing, false = constant, or the
   * FINAL size as a fraction of `size` — 0.5 = half, and >1 GROWS
   * (billowing smoke: 2.5 = swells to 2.5×). Default true. */
  shrink?: boolean | number;
  /** Fade alpha over life (default true). */
  fade?: boolean;
  /** Downward acceleration (default 0). Negative = embers rising. */
  gravity?: number;
  /** Velocity damping per second, 0..1 (default 0). */
  drag?: number;
  /** Smooth side-to-side wander acceleration, units/s² — snow, petals,
   * floating embers (default 0). */
  sway?: number;
  /** Sway oscillation frequency, cycles/s (default 1.5). */
  swayFreq?: number;
  /** One colour… */
  color?: string;
  /** …or a palette picked per particle. */
  colors?: string[];
  /** A colour ramp walked over the particle's life — a RAMPS name ('fire',
   * 'smoke', …) or custom hex stops. Overrides color/colors. */
  ramp?: RampName | string[];
  /** Alpha multiplier for the whole emit (default 1). */
  alpha?: number;
  /** Per-particle brightness flicker 0..1 (fireflies, embers, magic dust). */
  twinkle?: number;
  /** Additive blend — glows/fire/sparks (default false = normal alpha). */
  add?: boolean;
  /** Draw an atlas frame instead of a disc (debris, petals, chunks). */
  frame?: number;
  /** Random spin up to ±spin rad/s (only visible with `frame`). */
  spin?: number;
  /**
   * A name for this emitter, so the scene can DRAW it where it belongs:
   * `game.fx.draw(d, 'exhaust')` before the ship, `'sparks'` after it. Ungrouped
   * particles draw with the engine's own call, after the scene.
   */
  group?: string | number;
}

interface P {
  x: number; y: number; vx: number; vy: number;
  age: number; life: number; size: number;
  rot: number; spin: number;
  r: number; g: number; b: number; a: number;
  gravity: number; drag: number;
  sway: number; swayFreq: number; seed: number; twinkle: number;
  ramp: Rgba[] | null;
  fade: boolean; endSize: number; add: boolean; frame: number;
  group: string | number | null;
}

export class Particles {
  private pool: P[] = [];
  private alive = 0;
  private clock = 0;
  /** Groups already placed by the scene this frame — see draw(). */
  private placed = new Set<string | number>();

  /** Pass a seeded rng (e.g. mulberry32) for deterministic headless tests. */
  constructor(private rng: () => number = Math.random) {}

  /** Live particle count (for HUD/stress readouts). */
  get count(): number {
    return this.alive;
  }

  /** Spawn a burst. Call once for an explosion, every frame for a stream. */
  emit(opts: EmitOptions): void {
    const rng = this.rng;
    const count = opts.count ?? 12;
    const speed = opts.speed ?? 90;
    const speedVar = opts.speedVar ?? 40;
    const angle = opts.angle ?? 0;
    const spread = opts.spread ?? Math.PI * 2;
    const even = opts.even ?? false;
    const spawnR = opts.spawnRadius ?? 0;
    const life = opts.life ?? 0.7;
    const lifeVar = opts.lifeVar ?? 0.3;
    const size = opts.size ?? 4;
    const sizeVar = opts.sizeVar ?? 2;
    const alpha = opts.alpha ?? 1;
    const ramp = opts.ramp ? resolveRamp(opts.ramp) : null;
    const palette = opts.colors ?? [opts.color ?? '#ffffff'];
    const endSize = typeof opts.shrink === 'number'
      ? Math.max(0, opts.shrink)              // >1 = grows (smoke billows)
      : (opts.shrink ?? true) ? 0 : 1;
    for (let i = 0; i < count; i++) {
      const p = this.alive < this.pool.length ? this.pool[this.alive] : (this.pool.push(blank()), this.pool[this.alive]);
      this.alive++;
      p.group = opts.group ?? null;
      const a = even
        ? angle - spread / 2 + spread * ((i + 0.5) / count)
        : angle + (rng() - 0.5) * spread;
      const v = Math.max(0, speed + (rng() - 0.5) * 2 * speedVar);
      p.x = opts.x;
      p.y = opts.y;
      if (spawnR > 0) {
        const sa = rng() * Math.PI * 2;
        const sr = Math.sqrt(rng()) * spawnR;
        p.x += Math.cos(sa) * sr;
        p.y += Math.sin(sa) * sr;
      }
      p.vx = Math.cos(a) * v;
      p.vy = Math.sin(a) * v;
      p.age = 0;
      p.life = Math.max(0.05, life + (rng() - 0.5) * 2 * lifeVar);
      p.size = Math.max(0.5, size + (rng() - 0.5) * 2 * sizeVar);
      p.rot = 0;
      p.spin = (rng() - 0.5) * 2 * (opts.spin ?? 0);
      const first = ramp ? ramp[0] : rgba(palette[(rng() * palette.length) | 0]);
      p.r = first[0]; p.g = first[1]; p.b = first[2]; p.a = first[3] * alpha;
      p.ramp = ramp;
      p.gravity = opts.gravity ?? 0;
      p.drag = opts.drag ?? 0;
      p.sway = opts.sway ?? 0;
      p.swayFreq = opts.swayFreq ?? 1.5;
      p.seed = rng() * Math.PI * 2;
      p.twinkle = opts.twinkle ?? 0;
      p.fade = opts.fade ?? true;
      p.endSize = endSize;
      p.add = opts.add ?? false;
      p.frame = opts.frame ?? -1;
    }
  }

  /** A CONTINUOUS emitter — the only correct way to run a steady effect.
   * `rate` = particles per SECOND, wall clock: the engine owns the
   * accumulator, so alive = rate × life at ANY refresh rate (per-frame
   * emit() loops double on a 120 Hz display — emit() is for BURSTS).
   * Options are live; kill() stops the stream. */
  stream(opts: EmitOptions & { rate: number }): EmitOptions & { rate: number; dead: boolean; kill(): void } {
    const h = Object.assign({}, opts, {
      dead: false,
      kill(): void { this.dead = true; },
    });
    this.streams.push({ h, acc: 0 });
    return h;
  }

  private streams: Array<{ h: EmitOptions & { rate: number; dead: boolean }; acc: number }> = [];

  /** Age + integrate; recycles the dead (swap-remove — order is irrelevant). */
  update(dt: number): void {
    this.placed.clear();
    for (let i = this.streams.length - 1; i >= 0; i--) {
      const st = this.streams[i];
      if (st.h.dead) { this.streams.splice(i, 1); continue; }
      st.acc += st.h.rate * dt;
      const n = Math.floor(st.acc);
      st.acc -= n;
      if (n > 0) this.emit({ ...st.h, count: n });
    }
    this.clock += dt;
    for (let i = this.alive - 1; i >= 0; i--) {
      const p = this.pool[i];
      p.age += dt;
      if (p.age >= p.life) {
        this.alive--;
        this.pool[i] = this.pool[this.alive];
        this.pool[this.alive] = p; // keep it pooled
        continue;
      }
      const damp = p.drag > 0 ? Math.max(0, 1 - p.drag * dt) : 1;
      p.vx *= damp;
      p.vy = p.vy * damp + p.gravity * dt;
      if (p.sway) {
        const w = this.clock * p.swayFreq + p.seed;
        p.vx += Math.cos(w) * p.sway * dt;
        p.vy += Math.sin(w * 1.3) * p.sway * 0.35 * dt;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
  }

  /**
   * Push live particles into the frame AT THIS POINT in the draw order.
   *
   * Particles are ordinary display-list content: they land where you draw them,
   * so an exhaust plume goes BEHIND its ship simply by being drawn first.
   *
   * ```ts
   * override draw(d: Draw): void {
   *   super.draw(d);
   *   this.game.fx.draw(d, 'exhaust');   // …behind the ship
   *   d.sprite(shipFrame, x, y);
   *   this.game.fx.draw(d, 'sparks');    // …and in front of it
   * }
   * ```
   *
   * With a `group`, only that group draws, and it is remembered for the rest of
   * the frame. Without one, everything NOT already placed draws — which is what
   * the engine calls after the scene, so a game that never places anything
   * behaves exactly as before.
   */
  draw(d: Draw, group?: string | number): void {
    if (group !== undefined) this.placed.add(group);
    for (let i = 0; i < this.alive; i++) {
      const p = this.pool[i];
      if (group !== undefined ? p.group !== group : (p.group !== null && this.placed.has(p.group))) continue;
      const t = p.age / p.life;
      let alpha = p.fade ? p.a * (1 - t) : p.a;
      if (p.twinkle > 0) {
        alpha *= 1 - p.twinkle * (0.5 + 0.5 * Math.sin(this.clock * 11 + p.seed * 7));
      }
      const size = p.size * (1 - (1 - p.endSize) * t);
      if (alpha <= 0.004 || size <= 0.05) continue;
      let r = p.r, g = p.g, b = p.b;
      if (p.ramp) {
        const ci = t * (p.ramp.length - 1);
        const i0 = Math.min(p.ramp.length - 1, ci | 0);
        const i1 = Math.min(p.ramp.length - 1, i0 + 1);
        const f = ci - i0;
        const c0 = p.ramp[i0], c1 = p.ramp[i1];
        r = c0[0] + (c1[0] - c0[0]) * f;
        g = c0[1] + (c1[1] - c0[1]) * f;
        b = c0[2] + (c1[2] - c0[2]) * f;
      }
      d.part(p.x, p.y, size, p.rot, p.frame, r, g, b, alpha, p.add);
    }
  }

  /** Kill everything (scene change). */
  clear(): void {
    this.alive = 0;
  }
}

function blank(): P {
  return {
    x: 0, y: 0, vx: 0, vy: 0, age: 0, life: 1, size: 1, rot: 0, spin: 0,
    r: 1, g: 1, b: 1, a: 1, gravity: 0, drag: 0,
    sway: 0, swayFreq: 1.5, seed: 0, twinkle: 0, ramp: null,
    fade: true, endSize: 0, add: false, frame: -1, group: null,
  };
}
