// TRANSFORM COMPOSITION (parity-plan Phase 3 stage 4 — mesh parenting).
// The mesh instance format is pos + yaw/pitch/roll + per-axis size, so a
// parent chain composes through QUATERNIONS and decomposes back to the
// euler order the WGSL rotate() applies: R = Ry(yaw)·Rx(pitch)·Rz(roll).
// quatToEuler duplicates physics3d.ts's proven decomposition (that file's
// copy is private; same maths, same gimbal branch — pitch poles put the
// whole spin in yaw; a single frame's pose is always exact).
//
// Pure, allocation-light, dist-tested.

export type Quat = [number, number, number, number];   // x, y, z, w

/** Quaternion for the engine euler order: q = qY(yaw) · qX(pitch) · qZ(roll).
 * YAW HANDEDNESS: yaw is CLOCKWISE-from-above — increasing yaw turns to the
 * RIGHT (the mainstream / three.js / FPS sense). That is baked in here by
 * building qY from −yaw (sy is negated); the WGSL rotate(), forward(),
 * lookAtEuler(), physics and picking all share this one sign. */
export function eulerToQuat(yaw: number, pitch: number, roll: number): Quat {
  const cy = Math.cos(yaw / 2), sy = -Math.sin(yaw / 2);   // qY(−yaw): right-hand-turn yaw
  const cp = Math.cos(pitch / 2), sp = Math.sin(pitch / 2);
  const cr = Math.cos(roll / 2), sr = Math.sin(roll / 2);
  // qY · qX · qZ, expanded.
  return [
    sp * cy * cr + cp * sy * sr,
    sy * cp * cr - cy * sp * sr,
    cy * cp * sr - sy * sp * cr,
    cy * cp * cr + sy * sp * sr,
  ];
}

export function quatMul(a: Quat, b: Quat): Quat {
  return [
    a[3] * b[0] + a[0] * b[3] + a[1] * b[2] - a[2] * b[1],
    a[3] * b[1] - a[0] * b[2] + a[1] * b[3] + a[2] * b[0],
    a[3] * b[2] + a[0] * b[1] - a[1] * b[0] + a[2] * b[3],
    a[3] * b[3] - a[0] * b[0] - a[1] * b[1] - a[2] * b[2],
  ];
}

/** Rotate a point by a quaternion (q v q*). */
export function quatRotate(q: Quat, x: number, y: number, z: number): [number, number, number] {
  const [qx, qy, qz, qw] = q;
  // t = 2 q × v
  const tx = 2 * (qy * z - qz * y);
  const ty = 2 * (qz * x - qx * z);
  const tz = 2 * (qx * y - qy * x);
  return [
    x + qw * tx + qy * tz - qz * ty,
    y + qw * ty + qz * tx - qx * tz,
    z + qw * tz + qx * ty - qy * tx,
  ];
}

/** Quaternion → the engine's yaw/pitch/roll (Ry·Rx·Rz). physics3d's maths. */
export function quatToEuler(q: Quat): [number, number, number] {
  const [x, y, z, w] = q;
  const sinPitch = 2 * (w * x - y * z);
  // Yaw is negated on the way out to match eulerToQuat's qY(−yaw) — the
  // right-hand-turn (clockwise-from-above) convention. Pitch/roll unchanged.
  if (Math.abs(sinPitch) > 0.99999) {
    return [
      -Math.atan2(Math.sign(sinPitch) * 2 * (x * y - w * z), 1 - 2 * (y * y + z * z)),
      sinPitch > 0 ? Math.PI / 2 : -Math.PI / 2,
      0,
    ];
  }
  return [
    -Math.atan2(2 * (x * z + w * y), 1 - 2 * (x * x + y * y)),
    Math.asin(sinPitch),
    Math.atan2(2 * (x * y + w * z), 1 - 2 * (x * x + z * z)),
  ];
}

export interface ParentLike {
  x: number; y: number; z: number;
  yaw: number; pitch: number; roll: number;
  /** Uniform child-scale contribution (groups; mesh parents contribute 1). */
  scale?: number;
  parent?: ParentLike | null;
}

/**
 * Compose a child's LOCAL pose through its parent chain into world space.
 * Returns world position, world euler (engine order) and the accumulated
 * uniform scale. Guards against cycles (depth cap). Mesh parents contribute
 * position + rotation only — a crate's SIZE never inflates its rider;
 * `Group3d.scale` is the deliberate scaling knob.
 */
export function composeChain(
  localX: number, localY: number, localZ: number,
  localYaw: number, localPitch: number, localRoll: number,
  parent: ParentLike | null | undefined,
): { x: number; y: number; z: number; yaw: number; pitch: number; roll: number; scale: number } {
  let x = localX, y = localY, z = localZ;
  let q = eulerToQuat(localYaw, localPitch, localRoll);
  let scale = 1;
  let p = parent ?? null;
  let depth = 0;
  while (p && depth++ < 32) {
    const ps = p.scale ?? 1;
    const pq = eulerToQuat(p.yaw, p.pitch, p.roll);
    const [rx, ry, rz] = quatRotate(pq, x * ps, y * ps, z * ps);
    x = p.x + rx;
    y = p.y + ry;
    z = p.z + rz;
    q = quatMul(pq, q);
    scale *= ps;
    p = p.parent ?? null;
  }
  const [yaw, pitch, roll] = quatToEuler(q);
  return { x, y, z, yaw, pitch, roll, scale };
}

/** Yaw/pitch that aim local +Z at a target (engine rotate order, roll 0):
 * forward(yaw, pitch) = (−cos p · sin y, −sin p, cos p · cos y). */
export function lookAtEuler(
  fromX: number, fromY: number, fromZ: number,
  toX: number, toY: number, toZ: number,
): { yaw: number; pitch: number } {
  const dx = toX - fromX, dy = toY - fromY, dz = toZ - fromZ;
  const len = Math.hypot(dx, dy, dz) || 1;
  // atan2(−dx, dz): yaw increases CLOCKWISE-from-above (turn RIGHT), the
  // inverse of forward()'s −sin y. See eulerToQuat for the convention.
  return { yaw: Math.atan2(-dx, dz), pitch: -Math.asin(dy / len) };
}

/** Unit forward direction for a yaw/pitch (engine rotate order, roll 0) — the
 *  inverse of {@link lookAtEuler}: `forward(yaw, pitch) = (−cos p·sin y, −sin p,
 *  cos p·cos y)`. `+Z` is forward at yaw 0; INCREASING yaw turns to the RIGHT
 *  (mainstream / three.js / FPS). Use it for first-person movement and camera
 *  aim (`world.camera.face`). */
export function forward(yaw: number, pitch = 0): { x: number; y: number; z: number } {
  const cp = Math.cos(pitch);
  return { x: -cp * Math.sin(yaw), y: -Math.sin(pitch), z: cp * Math.cos(yaw) };
}
