// 3D SPLINE PATHS (parity-plan Phase 5) — Path3d: a Catmull-Rom curve
// through 3D control points, arc-length parameterised, with a PARALLEL-
// TRANSPORT frame at every sample (the same no-twist maths as tubeVerts,
// generalised): coaster tracks, patrol routes, camera rails, and the PATH
// particle-emitter shape all sample the one baked table.
//
// Pure by design (no GPU imports): everything here is dist-testable.
// t is always the ARC-LENGTH fraction 0..1 — constant speed by distance,
// not by control-point spacing.

export interface Path3dOptions {
  /** Join the last point back to the first (loops: coasters, patrols). */
  closed?: boolean;
  /** Samples baked per segment (default 24; more = smoother frames). */
  samplesPerSegment?: number;
}

export interface PathFrame {
  x: number; y: number; z: number;
  /** Unit tangent — the travel direction. */
  tx: number; ty: number; tz: number;
  /** Parallel-transported unit normal (no roll flips around loops). */
  nx: number; ny: number; nz: number;
  /** Binormal = tangent × normal. */
  bx: number; by: number; bz: number;
}

type P3 = { x: number; y: number; z: number };

/** CENTRIPETAL Catmull-Rom on one segment (p0..p3 window, u 0..1 across
 * p1→p2) — Barry–Goldman with sqrt-chord knots. Centripetal is the game
 * choice: uniform CR OVERSHOOTS wildly when control points are unevenly
 * spaced (a 1-unit hop next to a 99-unit run loops back on itself);
 * centripetal never self-intersects within a segment. */
export function catmullRom3(
  p0: number[], p1: number[], p2: number[], p3: number[], u: number,
): [number, number, number] {
  const knot = (a: number[], b: number[], t: number): number =>
    t + Math.max(1e-6, Math.sqrt(Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2])));
  const t0 = 0;
  const t1 = knot(p0, p1, t0);
  const t2 = knot(p1, p2, t1);
  const t3 = knot(p2, p3, t2);
  const t = t1 + (t2 - t1) * u;
  const mix = (a: number[], b: number[], ta: number, tb: number): number[] => {
    const k = (t - ta) / (tb - ta);
    return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
  };
  const A1 = mix(p0, p1, t0, t1);
  const A2 = mix(p1, p2, t1, t2);
  const A3 = mix(p2, p3, t2, t3);
  const B1 = mix(A1, A2, t0, t2);
  const B2 = mix(A2, A3, t1, t3);
  const C = mix(B1, B2, t1, t2);
  return [C[0], C[1], C[2]];
}

export class Path3d {
  /** Total arc length (world units). */
  readonly length: number;
  readonly closed: boolean;

  // Baked sample tables: positions, cumulative length, transported frames.
  private px: Float64Array; private py: Float64Array; private pz: Float64Array;
  private tx: Float64Array; private ty: Float64Array; private tz: Float64Array;
  private nx: Float64Array; private ny: Float64Array; private nz: Float64Array;
  private cum: Float64Array;
  private n: number;

  constructor(points: Array<[number, number, number]> | P3[], opts: Path3dOptions = {}) {
    const pts: number[][] = points.map((p) => Array.isArray(p) ? [p[0], p[1], p[2]] : [p.x, p.y, p.z]);
    if (pts.length < 2) throw new Error('Path3d: need at least 2 points');
    this.closed = opts.closed ?? false;
    const per = Math.max(4, Math.floor(opts.samplesPerSegment ?? 24));
    const segs = this.closed ? pts.length : pts.length - 1;
    const n = this.n = segs * per + 1;

    this.px = new Float64Array(n); this.py = new Float64Array(n); this.pz = new Float64Array(n);
    this.tx = new Float64Array(n); this.ty = new Float64Array(n); this.tz = new Float64Array(n);
    this.nx = new Float64Array(n); this.ny = new Float64Array(n); this.nz = new Float64Array(n);
    this.cum = new Float64Array(n);

    // Control-point window with end handling: closed wraps, open clamps.
    const at = (i: number): number[] => {
      const m = pts.length;
      if (this.closed) return pts[((i % m) + m) % m];
      return pts[Math.min(m - 1, Math.max(0, i))];
    };

    // 1. Sample positions.
    for (let s = 0; s < segs; s++) {
      for (let k = 0; k < per; k++) {
        const i = s * per + k;
        const [x, y, z] = catmullRom3(at(s - 1), at(s), at(s + 1), at(s + 2), k / per);
        this.px[i] = x; this.py[i] = y; this.pz[i] = z;
      }
    }
    {
      const last = this.closed ? at(0) : at(segs);
      const end = this.closed
        ? [this.px[0], this.py[0], this.pz[0]]
        : catmullRom3(at(segs - 1), at(segs), at(segs + 1), at(segs + 2), 1);
      this.px[n - 1] = this.closed ? last[0] : end[0];
      this.py[n - 1] = this.closed ? last[1] : end[1];
      this.pz[n - 1] = this.closed ? last[2] : end[2];
    }

    // 2. Cumulative arc length + central-difference tangents.
    for (let i = 1; i < n; i++) {
      this.cum[i] = this.cum[i - 1] + Math.hypot(
        this.px[i] - this.px[i - 1], this.py[i] - this.py[i - 1], this.pz[i] - this.pz[i - 1],
      );
    }
    this.length = this.cum[n - 1];
    for (let i = 0; i < n; i++) {
      const a = Math.max(0, i - 1), b = Math.min(n - 1, i + 1);
      let vx = this.px[b] - this.px[a], vy = this.py[b] - this.py[a], vz = this.pz[b] - this.pz[a];
      const l = Math.hypot(vx, vy, vz) || 1;
      this.tx[i] = vx / l; this.ty[i] = vy / l; this.tz[i] = vz / l;
    }

    // 3. Parallel-transport the normal frame down the samples (tubeAlong's
    // rotation-between-tangents, generalised out of the mesh builder).
    {
      // The initial normal is WORLD-UP projected off the tangent: paths are
      // tracks, and "up" should start upright — parallel transport then
      // carries it through vertical loops, INVERTING over the top, which is
      // exactly what a coaster (and a banking camera) wants. Fall back to
      // +x when the path launches straight up.
      const t0 = [this.tx[0], this.ty[0], this.tz[0]];
      let ax = -t0[0] * t0[1], ay = 1 - t0[1] * t0[1], az = -t0[2] * t0[1];
      let l = Math.hypot(ax, ay, az);
      if (l < 1e-4) {
        ax = 1 - t0[0] * t0[0]; ay = -t0[1] * t0[0]; az = -t0[2] * t0[0];
        l = Math.hypot(ax, ay, az) || 1;
      }
      this.nx[0] = ax / l; this.ny[0] = ay / l; this.nz[0] = az / l;
    }
    for (let i = 1; i < n; i++) {
      const a = [this.tx[i - 1], this.ty[i - 1], this.tz[i - 1]];
      const c = [this.tx[i], this.ty[i], this.tz[i]];
      let ax = a[1] * c[2] - a[2] * c[1], ay = a[2] * c[0] - a[0] * c[2], az = a[0] * c[1] - a[1] * c[0];
      const l = Math.hypot(ax, ay, az);
      if (l < 1e-9) {
        this.nx[i] = this.nx[i - 1]; this.ny[i] = this.ny[i - 1]; this.nz[i] = this.nz[i - 1];
        continue;
      }
      ax /= l; ay /= l; az /= l;
      const dot = Math.min(1, Math.max(-1, a[0] * c[0] + a[1] * c[1] + a[2] * c[2]));
      const ang = Math.acos(dot), cs = Math.cos(ang), sn = Math.sin(ang);
      const v = [this.nx[i - 1], this.ny[i - 1], this.nz[i - 1]];
      const d = (1 - cs) * (ax * v[0] + ay * v[1] + az * v[2]);
      this.nx[i] = v[0] * cs + (ay * v[2] - az * v[1]) * sn + ax * d;
      this.ny[i] = v[1] * cs + (az * v[0] - ax * v[2]) * sn + ay * d;
      this.nz[i] = v[2] * cs + (ax * v[1] - ay * v[0]) * sn + az * d;
    }
    // Closed loops: unwind the accumulated twist so the frame at t=1 meets
    // the frame at t=0 (the tube builder's shear fix, applied to the table).
    if (this.closed) {
      const nEnd = [this.nx[n - 1], this.ny[n - 1], this.nz[n - 1]];
      const n0 = [this.nx[0], this.ny[0], this.nz[0]];
      const t0 = [this.tx[0], this.ty[0], this.tz[0]];
      const b0 = [
        t0[1] * n0[2] - t0[2] * n0[1],
        t0[2] * n0[0] - t0[0] * n0[2],
        t0[0] * n0[1] - t0[1] * n0[0],
      ];
      const twist = Math.atan2(
        nEnd[0] * b0[0] + nEnd[1] * b0[1] + nEnd[2] * b0[2],
        nEnd[0] * n0[0] + nEnd[1] * n0[1] + nEnd[2] * n0[2],
      );
      for (let i = 1; i < n; i++) {
        const ang = -twist * (i / (n - 1)), cs = Math.cos(ang), sn = Math.sin(ang);
        const t = [this.tx[i], this.ty[i], this.tz[i]];
        const v = [this.nx[i], this.ny[i], this.nz[i]];
        const d = (1 - cs) * (t[0] * v[0] + t[1] * v[1] + t[2] * v[2]);
        this.nx[i] = v[0] * cs + (t[1] * v[2] - t[2] * v[1]) * sn + t[0] * d;
        this.ny[i] = v[1] * cs + (t[2] * v[0] - t[0] * v[2]) * sn + t[1] * d;
        this.nz[i] = v[2] * cs + (t[0] * v[1] - t[1] * v[0]) * sn + t[2] * d;
      }
    }
  }

  /** Sample index + blend for an arc-length fraction (binary search). */
  private locate(t: number): [number, number] {
    let f = this.closed ? ((t % 1) + 1) % 1 : Math.min(1, Math.max(0, t));
    const d = f * this.length;
    let lo = 0, hi = this.n - 1;
    while (lo + 1 < hi) {
      const mid = (lo + hi) >> 1;
      if (this.cum[mid] <= d) lo = mid; else hi = mid;
    }
    const span = this.cum[hi] - this.cum[lo];
    return [lo, span > 1e-12 ? (d - this.cum[lo]) / span : 0];
  }

  /** Position at arc-length fraction t (0..1; closed paths wrap). */
  at(t: number): P3 {
    const [i, u] = this.locate(t);
    return {
      x: this.px[i] + (this.px[i + 1] - this.px[i]) * u,
      y: this.py[i] + (this.py[i + 1] - this.py[i]) * u,
      z: this.pz[i] + (this.pz[i + 1] - this.pz[i]) * u,
    };
  }

  /** Position at a distance in world units along the path. */
  atDist(d: number): P3 {
    return this.at(this.length > 0 ? d / this.length : 0);
  }

  /** Full frame at t: position + tangent + parallel-transported normal +
   * binormal (all unit) — orient a cart, bank a camera, place a rail tie. */
  frame(t: number): PathFrame {
    const [i, u] = this.locate(t);
    const lerp = (a: Float64Array): number => a[i] + (a[i + 1] - a[i]) * u;
    let tx = lerp(this.tx), ty = lerp(this.ty), tz = lerp(this.tz);
    let l = Math.hypot(tx, ty, tz) || 1; tx /= l; ty /= l; tz /= l;
    let nx = lerp(this.nx), ny = lerp(this.ny), nz = lerp(this.nz);
    // Re-orthogonalise the lerped normal against the tangent.
    const dot = nx * tx + ny * ty + nz * tz;
    nx -= tx * dot; ny -= ty * dot; nz -= tz * dot;
    l = Math.hypot(nx, ny, nz) || 1; nx /= l; ny /= l; nz /= l;
    return {
      x: lerp(this.px), y: lerp(this.py), z: lerp(this.pz),
      tx, ty, tz, nx, ny, nz,
      bx: ty * nz - tz * ny, by: tz * nx - tx * nz, bz: tx * ny - ty * nx,
    };
  }

  /** n points evenly spaced by ARC LENGTH — feed world.tube({ path }) or a
   * vector polyline directly. Closed paths omit the duplicate end point. */
  points(count: number): Array<[number, number, number]> {
    const out: Array<[number, number, number]> = [];
    const m = Math.max(2, Math.floor(count));
    for (let i = 0; i < m; i++) {
      const t = this.closed ? i / m : i / (m - 1);
      const p = this.at(t);
      out.push([p.x, p.y, p.z]);
    }
    return out;
  }
}

// ---------------------------------------------------------------------------
// DYNAMIC PATHS — a rolling window: add waypoints AHEAD, trim what's BEHIND,
// ride smoothly forever. The drone weaving through the night city; a monster
// tracking across a landscape without a pre-authored mega-path.
//
// The design constraints that make it seamless:
// - Riding is addressed by ABSOLUTE DISTANCE (monotonic since birth), never
//   by the 0..1 fraction — a growing length would remap fractions and
//   teleport the rider.
// - A Catmull-Rom segment is only BAKED once its p+2 control point exists,
//   so no already-ridable track ever reshapes under the rider. The last two
//   waypoints are always "provisional" — head stays ~2 points behind add().
// - Parallel transport CONTINUES from the previous bake, so frames never
//   pop across appends; trim() drops samples from the front only.
// ---------------------------------------------------------------------------

export class DynamicPath3d {
  /** Samples per baked segment (fixed at construction). */
  private per: number;
  private pts: number[][] = [];
  private ptsBase = 0;          // control points dropped from the front
  private bakedSegs = 0;        // segments baked so far (absolute)
  // Parallel sample arrays, absolute distances in cum (pruned from front).
  private sx: number[] = []; private sy: number[] = []; private sz: number[] = [];
  private stx: number[] = []; private sty: number[] = []; private stz: number[] = [];
  private snx: number[] = []; private sny: number[] = []; private snz: number[] = [];
  private cum: number[] = [];

  constructor(opts: { samplesPerSegment?: number } = {}) {
    this.per = Math.max(4, Math.floor(opts.samplesPerSegment ?? 16));
  }

  /** Distance at the START of the ridable window (advances with trim()). */
  get start(): number { return this.cum.length ? this.cum[0] : 0; }
  /** Distance at the END of the ridable window (grows with add()). Keep
   * adding while `head - riderDist` shrinks — the rider must never catch
   * the head. 0 until three waypoints exist. */
  get head(): number { return this.cum.length ? this.cum[this.cum.length - 1] : 0; }
  /** Ridable yet? (needs 3 waypoints for the first baked segment). */
  get ready(): boolean { return this.cum.length > 1; }

  /** Append a waypoint AHEAD. Bakes every segment that just became stable
   * and drops control points the baker no longer needs. */
  add(x: number | { x: number; y: number; z: number }, y = 0, z = 0): void {
    const p = typeof x === 'number' ? [x, y, z] : [x.x, x.y, x.z];
    this.pts.push(p);
    const total = this.ptsBase + this.pts.length;   // absolute point count
    while (this.bakedSegs <= total - 3) this.bakeSeg(this.bakedSegs++);
    // The next bake (segment bakedSegs) needs points bakedSegs-1 onward.
    while (this.ptsBase < this.bakedSegs - 1) { this.pts.shift(); this.ptsBase++; }
  }

  private bakeSeg(s: number): void {
    const at = (i: number): number[] => this.pts[Math.max(0, i - this.ptsBase)];
    const p0 = at(s - 1), p1 = at(s), p2 = at(s + 1), p3 = at(s + 2);
    const first = this.cum.length === 0;
    // k=0 duplicates the previous segment's end — skip it unless first.
    for (let k = first ? 0 : 1; k <= this.per; k++) {
      const [x, yy, zz] = catmullRom3(p0, p1, p2, p3, k / this.per);
      const n = this.cum.length;
      const d = n ? this.cum[n - 1] + Math.hypot(x - this.sx[n - 1], yy - this.sy[n - 1], zz - this.sz[n - 1]) : 0;
      this.sx.push(x); this.sy.push(yy); this.sz.push(zz);
      this.cum.push(d);
      this.stx.push(0); this.sty.push(0); this.stz.push(0);   // tangents below
      this.snx.push(0); this.sny.push(0); this.snz.push(0);
    }
    // Tangents: central differences, INCLUDING re-fixing the junction sample
    // (its forward neighbour only just arrived); then continue the parallel
    // transport from the last sample that already had a frame.
    const n = this.cum.length;
    const from = Math.max(0, n - this.per - 2);
    for (let i = from; i < n; i++) {
      const a = Math.max(0, i - 1), b = Math.min(n - 1, i + 1);
      const vx = this.sx[b] - this.sx[a], vy = this.sy[b] - this.sy[a], vz = this.sz[b] - this.sz[a];
      const l = Math.hypot(vx, vy, vz) || 1;
      this.stx[i] = vx / l; this.sty[i] = vy / l; this.stz[i] = vz / l;
    }
    let i0 = from;
    if (i0 === 0) {
      // First bake: world-up initial normal (the Path3d convention).
      const tx = this.stx[0], ty = this.sty[0], tz = this.stz[0];
      let ax = -tx * ty, ay = 1 - ty * ty, az = -tz * ty;
      let l = Math.hypot(ax, ay, az);
      if (l < 1e-4) { ax = 1 - tx * tx; ay = -ty * tx; az = -tz * tx; l = Math.hypot(ax, ay, az) || 1; }
      this.snx[0] = ax / l; this.sny[0] = ay / l; this.snz[0] = az / l;
      i0 = 1;
    }
    for (let i = i0; i < n; i++) {
      const a = [this.stx[i - 1], this.sty[i - 1], this.stz[i - 1]];
      const c = [this.stx[i], this.sty[i], this.stz[i]];
      let ax = a[1] * c[2] - a[2] * c[1], ay = a[2] * c[0] - a[0] * c[2], az = a[0] * c[1] - a[1] * c[0];
      const l = Math.hypot(ax, ay, az);
      if (l < 1e-9) {
        this.snx[i] = this.snx[i - 1]; this.sny[i] = this.sny[i - 1]; this.snz[i] = this.snz[i - 1];
        continue;
      }
      ax /= l; ay /= l; az /= l;
      const dt = Math.min(1, Math.max(-1, a[0] * c[0] + a[1] * c[1] + a[2] * c[2]));
      const ang = Math.acos(dt), cs = Math.cos(ang), sn = Math.sin(ang);
      const v = [this.snx[i - 1], this.sny[i - 1], this.snz[i - 1]];
      const dd = (1 - cs) * (ax * v[0] + ay * v[1] + az * v[2]);
      this.snx[i] = v[0] * cs + (ay * v[2] - az * v[1]) * sn + ax * dd;
      this.sny[i] = v[1] * cs + (az * v[0] - ax * v[2]) * sn + ay * dd;
      this.snz[i] = v[2] * cs + (ax * v[1] - ay * v[0]) * sn + az * dd;
    }
  }

  /** Drop everything WHOLLY behind distance d (keeps the bracketing sample
   * so frameAt(d) still interpolates). Distances stay absolute. */
  trim(d: number): void {
    let drop = 0;
    while (drop + 1 < this.cum.length && this.cum[drop + 1] <= d) drop++;
    if (!drop) return;
    for (const a of [this.sx, this.sy, this.sz, this.stx, this.sty, this.stz, this.snx, this.sny, this.snz, this.cum]) {
      a.splice(0, drop);
    }
  }

  private locate(d: number): [number, number] {
    const n = this.cum.length;
    const dd = Math.min(this.cum[n - 1], Math.max(this.cum[0], d));
    let lo = 0, hi = n - 1;
    while (lo + 1 < hi) {
      const mid = (lo + hi) >> 1;
      if (this.cum[mid] <= dd) lo = mid; else hi = mid;
    }
    const span = this.cum[hi] - this.cum[lo];
    return [lo, span > 1e-12 ? (dd - this.cum[lo]) / span : 0];
  }

  /** Position at ABSOLUTE distance d (clamped to [start, head]). */
  at(d: number): { x: number; y: number; z: number } {
    if (!this.ready) throw new Error('DynamicPath3d: add at least 3 waypoints first');
    const [i, u] = this.locate(d);
    return {
      x: this.sx[i] + (this.sx[i + 1] - this.sx[i]) * u,
      y: this.sy[i] + (this.sy[i + 1] - this.sy[i]) * u,
      z: this.sz[i] + (this.sz[i + 1] - this.sz[i]) * u,
    };
  }

  /** Full frame at ABSOLUTE distance d — same contract as Path3d.frame. */
  frameAt(d: number): PathFrame {
    if (!this.ready) throw new Error('DynamicPath3d: add at least 3 waypoints first');
    const [i, u] = this.locate(d);
    const lerp = (a: number[]): number => a[i] + (a[i + 1] - a[i]) * u;
    let tx = lerp(this.stx), ty = lerp(this.sty), tz = lerp(this.stz);
    let l = Math.hypot(tx, ty, tz) || 1; tx /= l; ty /= l; tz /= l;
    let nx = lerp(this.snx), ny = lerp(this.sny), nz = lerp(this.snz);
    const dot = nx * tx + ny * ty + nz * tz;
    nx -= tx * dot; ny -= ty * dot; nz -= tz * dot;
    l = Math.hypot(nx, ny, nz) || 1; nx /= l; ny /= l; nz /= l;
    return {
      x: lerp(this.sx), y: lerp(this.sy), z: lerp(this.sz),
      tx, ty, tz, nx, ny, nz,
      bx: ty * nz - tz * ny, by: tz * nx - tx * nz, bz: tx * ny - ty * nx,
    };
  }

  /** n points between two absolute distances — draw the plotted route. */
  pointsBetween(d0: number, d1: number, n: number): Array<[number, number, number]> {
    const out: Array<[number, number, number]> = [];
    const m = Math.max(2, Math.floor(n));
    for (let i = 0; i < m; i++) {
      const p = this.at(d0 + ((d1 - d0) * i) / (m - 1));
      out.push([p.x, p.y, p.z]);
    }
    return out;
  }
}
