// Pure animation/rig maths for GLB skeletal + node animation: quaternion
// slerp, TRS→mat4 baking, keyframe channel sampling, out-of-order world
// composition, joint palettes and the AnimMixer (clip playback + crossfade).
// Column-major mat4s matching src/lib/math3d.ts conventions (m[col*4+row]).
// No DOM, no GPU — headlessly tested against the built bundle.

import type { GlbRig, GlbChannel, GlbSkinOut } from './glb.js';

// ─── Quaternions ─────────────────────────────────────────────────────────────

/**
 * Shortest-path spherical lerp between quats a and b (components, not
 * objects — the hot path never allocates inputs). When the quats are
 * near-parallel the sin() denominator degenerates, so we fall back to
 * normalized lerp, which is indistinguishable there.
 */
export function quatSlerp(
  ax: number, ay: number, az: number, aw: number,
  bx: number, by: number, bz: number, bw: number,
  t: number,
): [number, number, number, number] {
  let dot = ax * bx + ay * by + az * bz + aw * bw;
  if (dot < 0) {
    // Negate b: q and -q are the same rotation, take the short arc.
    bx = -bx; by = -by; bz = -bz; bw = -bw;
    dot = -dot;
  }
  let ka: number;
  let kb: number;
  if (dot > 0.9995) {
    // Near-parallel: nlerp.
    ka = 1 - t;
    kb = t;
  } else {
    const theta = Math.acos(Math.min(1, dot));
    const sinTheta = Math.sin(theta);
    ka = Math.sin((1 - t) * theta) / sinTheta;
    kb = Math.sin(t * theta) / sinTheta;
  }
  let x = ka * ax + kb * bx;
  let y = ka * ay + kb * by;
  let z = ka * az + kb * bz;
  let w = ka * aw + kb * bw;
  const len = Math.hypot(x, y, z, w) || 1;
  x /= len; y /= len; z /= len; w /= len;
  return [x, y, z, w];
}

// ─── Matrices ────────────────────────────────────────────────────────────────

/**
 * Bake translation + quaternion + scale into a column-major mat4 (T·R·S —
 * scale first, then rotate, then translate; same convention as math3d).
 */
export function trsToMat4(
  t: readonly number[], r: readonly number[], s: readonly number[],
  out?: Float32Array,
): Float32Array {
  const m = out ?? new Float32Array(16);
  const x = r[0], y = r[1], z = r[2], w = r[3];
  const x2 = x + x, y2 = y + y, z2 = z + z;
  const xx = x * x2, xy = x * y2, xz = x * z2;
  const yy = y * y2, yz = y * z2, zz = z * z2;
  const wx = w * x2, wy = w * y2, wz = w * z2;
  const sx = s[0], sy = s[1], sz = s[2];
  m[0] = (1 - (yy + zz)) * sx;
  m[1] = (xy + wz) * sx;
  m[2] = (xz - wy) * sx;
  m[3] = 0;
  m[4] = (xy - wz) * sy;
  m[5] = (1 - (xx + zz)) * sy;
  m[6] = (yz + wx) * sy;
  m[7] = 0;
  m[8] = (xz + wy) * sz;
  m[9] = (yz - wx) * sz;
  m[10] = (1 - (xx + yy)) * sz;
  m[11] = 0;
  m[12] = t[0];
  m[13] = t[1];
  m[14] = t[2];
  m[15] = 1;
  return m;
}

/** out[oo..oo+16] = a[ao..] × b[bo..] — offset multiply, zero allocation. */
function mulAt(
  a: Float32Array, ao: number,
  b: Float32Array, bo: number,
  out: Float32Array, oo: number,
): void {
  for (let c = 0; c < 4; c++) {
    const b0 = b[bo + c * 4], b1 = b[bo + c * 4 + 1], b2 = b[bo + c * 4 + 2], b3 = b[bo + c * 4 + 3];
    for (let r = 0; r < 4; r++) {
      out[oo + c * 4 + r] =
        a[ao + r] * b0 + a[ao + 4 + r] * b1 + a[ao + 8 + r] * b2 + a[ao + 12 + r] * b3;
    }
  }
}

/** out = a × b, allocation-free (out must not alias a or b). Column-major. */
export function mat4MulTo(a: Float32Array, b: Float32Array, out: Float32Array): void {
  mulAt(a, 0, b, 0, out, 0);
}

// ─── Channel sampling ────────────────────────────────────────────────────────

/**
 * Sample one animation channel at time `tt` (caller pre-wraps for looping)
 * into `out` (3 floats for translation/scale, 4 for rotation). Binary-searches
 * the keyframe span; STEP holds the left key, LINEAR lerps (slerp for
 * rotation), CUBICSPLINE reads the middle element of each in/value/out triplet
 * and lerps linearly between keys. Clamps outside the keyframe range.
 */
export function sampleChannel(ch: GlbChannel, tt: number, out: Float32Array): void {
  const comps = ch.path === 'rotation' ? 4 : 3;
  const cubic = ch.interpolation === 'CUBICSPLINE';
  const stride = cubic ? comps * 3 : comps;
  // CUBICSPLINE keys pack [inTangent, value, outTangent] — value is the middle.
  const valueOfs = cubic ? comps : 0;
  const times = ch.times;
  const values = ch.values;
  const n = times.length;

  const read = (key: number, into: Float32Array, at: number): void => {
    const base = key * stride + valueOfs;
    for (let i = 0; i < comps; i++) into[at + i] = values[base + i];
  };

  if (n === 0) return;
  if (tt <= times[0] || n === 1) { read(0, out, 0); return; }
  if (tt >= times[n - 1]) { read(n - 1, out, 0); return; }

  // Binary search: greatest i with times[i] <= tt (and i+1 exists).
  let lo = 0;
  let hi = n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (times[mid] <= tt) lo = mid; else hi = mid;
  }

  if (ch.interpolation === 'STEP') { read(lo, out, 0); return; }

  const t0 = times[lo];
  const t1 = times[hi];
  const f = t1 > t0 ? (tt - t0) / (t1 - t0) : 0;
  const a = lo * stride + valueOfs;
  const b = hi * stride + valueOfs;

  if (ch.path === 'rotation') {
    const q = quatSlerp(
      values[a], values[a + 1], values[a + 2], values[a + 3],
      values[b], values[b + 1], values[b + 2], values[b + 3],
      f,
    );
    out[0] = q[0]; out[1] = q[1]; out[2] = q[2]; out[3] = q[3];
  } else {
    for (let i = 0; i < comps; i++) out[i] = values[a + i] + (values[b + i] - values[a + i]) * f;
  }
}

// ─── World composition ───────────────────────────────────────────────────────

// Module-level scratch for composeWorlds' resolved flags — lazily grown,
// reused across calls (no per-frame allocation once warm).
let resolvedScratch = new Uint8Array(0);

/**
 * Compose world matrices for every node from local matrices. `parents[i]` is
 * the parent node index or -1 for roots — parents may appear ANYWHERE in the
 * array (glTF imposes no parent-before-child order), so nodes are resolved
 * iteratively until every one has a resolved parent. locals and worlds are
 * 16-floats-per-node arrays; worlds must not alias locals.
 */
export function composeWorlds(
  parents: Int32Array | number[],
  locals: Float32Array,
  worlds: Float32Array,
): void {
  const n = parents.length;
  if (resolvedScratch.length < n) resolvedScratch = new Uint8Array(n);
  else resolvedScratch.fill(0, 0, n);
  let remaining = n;
  while (remaining > 0) {
    const before = remaining;
    for (let i = 0; i < n; i++) {
      if (resolvedScratch[i]) continue;
      const p = parents[i];
      if (p < 0) {
        worlds.set(locals.subarray(i * 16, i * 16 + 16), i * 16);
      } else if (resolvedScratch[p]) {
        mulAt(worlds, p * 16, locals, i * 16, worlds, i * 16);
      } else {
        continue;
      }
      resolvedScratch[i] = 1;
      remaining--;
    }
    // Cycle guard: a malformed rig with a parent loop must not hang the frame.
    if (remaining === before) break;
  }
}

/**
 * palette[j] = worlds[skin.joints[j]] × inverseBind[j] — 16 floats per joint
 * into `out`. Allocation-free hot path, called per frame per skinned model.
 */
export function jointPalette(skin: GlbSkinOut, worlds: Float32Array, out: Float32Array): void {
  const joints = skin.joints;
  const ib = skin.inverseBind;
  for (let j = 0; j < joints.length; j++) {
    mulAt(worlds, joints[j] * 16, ib, j * 16, out, j * 16);
  }
}

// ─── TRS decomposition (matrix → mesh-channel yaw/pitch/roll) ────────────────

/**
 * Decompose an affine TRS matrix (glTF forbids skew) into translation, scale
 * and Euler angles in the ENGINE's rotation order: the mesh shader applies
 * roll (Z), then pitch (X), then yaw (Y) — R = Ry(yaw)·Rx(pitch)·Rz(roll) —
 * so writing these onto a mesh's yaw/pitch/roll reproduces the matrix's
 * orientation exactly. Same convention (gimbal branch included) as
 * physics3d's quatToEuler: at pitch = ±90° roll is folded into yaw. Scale is
 * per-column length; a negative determinant folds into the sign of s.z.
 */
export function decomposeTRS(m: Float32Array): {
  t: [number, number, number];
  e: [number, number, number]; // [yaw, pitch, roll]
  s: [number, number, number];
} {
  const t: [number, number, number] = [m[12], m[13], m[14]];
  let sx = Math.hypot(m[0], m[1], m[2]);
  let sy = Math.hypot(m[4], m[5], m[6]);
  let sz = Math.hypot(m[8], m[9], m[10]);
  // det of the upper 3×3 — negative means one axis is mirrored; glTF's
  // decomposition convention folds the flip into z.
  const det =
    m[0] * (m[5] * m[10] - m[6] * m[9]) -
    m[4] * (m[1] * m[10] - m[2] * m[9]) +
    m[8] * (m[1] * m[6] - m[2] * m[5]);
  if (det < 0) sz = -sz;
  const isx = sx ? 1 / sx : 0;
  const isy = sy ? 1 / sy : 0;
  const isz = sz ? 1 / sz : 0;

  // Pure-rotation elements r(row,col): r12 = -sin(pitch); yaw = atan2(r02, r22);
  // roll = atan2(r10, r11). Column-major: r(row,col) = m[col*4+row] / s(col).
  const sinPitch = Math.max(-1, Math.min(1, -m[9] * isz)); // -r12
  let yaw: number;
  let pitch: number;
  let roll: number;
  if (Math.abs(sinPitch) > 0.99999) {
    // Gimbal pole: pitch = ±90°, yaw and roll collapse onto one axis — put it
    // all in yaw (matching physics3d): yaw = atan2(sign(sinPitch)·r01, r00).
    pitch = sinPitch > 0 ? Math.PI / 2 : -Math.PI / 2;
    roll = 0;
    // Yaw negated to match the shader's right-hand-turn rotate() (see
    // transform3d) — a node matrix reproduces the same on-screen orientation.
    yaw = -Math.atan2(Math.sign(sinPitch) * m[4] * isy, m[0] * isx);
  } else {
    pitch = Math.asin(sinPitch);
    yaw = -Math.atan2(m[8] * isz, m[10] * isz);
    roll = Math.atan2(m[1] * isx, m[5] * isy);
  }
  return { t, e: [yaw, pitch, roll], s: [sx, sy, sz] };
}

// ─── AnimMixer ───────────────────────────────────────────────────────────────

const POSE = 10; // floats per node pose: t(3) + r(4) + s(3)

interface ClipState {
  index: number;
  time: number;
  loop: boolean;
}

/**
 * The pure clip mixer: tracks the active clip plus an optional crossfade from
 * the previous one. Every update(dt) advances time, samples each animated
 * channel, blends poses during a fade (lerp t/s, slerp r), bakes local
 * matrices and composes world matrices. Nodes no clip ever animates keep
 * their rest matrices, computed once. All per-frame work is allocation-free.
 */
export class AnimMixer {
  /** Clip names, in rig order — play() accepts a name or this index. */
  readonly anims: readonly string[];

  /** Local (16/node) and world (16/node) matrices, rebuilt by update(). */
  readonly locals: Float32Array;
  readonly worlds: Float32Array;

  /** Seconds into the current clip. */
  time = 0;
  /** True while a clip is active (one-shots flip to false when they finish). */
  playing = false;
  /** One-shot finished — sticky until the next play(). */
  done = false;

  private readonly rig: GlbRig;
  private readonly parents: Int32Array;
  private readonly restPose: Float32Array;   // POSE floats per node
  private readonly poseA: Float32Array;      // current clip's pose
  private readonly poseB: Float32Array;      // fading-out clip's pose
  private readonly animated: Uint8Array;     // 1 = some clip animates this node
  private readonly sampleScratch = new Float32Array(4);

  private current: ClipState | null = null;
  private previous: ClipState | null = null;
  private fadeTime = 0;
  private fadeDuration = 0;

  constructor(rig: GlbRig) {
    this.rig = rig;
    const n = rig.nodes.length;
    this.anims = rig.anims.map((a) => a.name);
    this.parents = new Int32Array(n);
    this.locals = new Float32Array(n * 16);
    this.worlds = new Float32Array(n * 16);
    this.restPose = new Float32Array(n * POSE);
    this.poseA = new Float32Array(n * POSE);
    this.poseB = new Float32Array(n * POSE);
    this.animated = new Uint8Array(n);

    for (const anim of rig.anims) {
      for (const ch of anim.channels) this.animated[ch.node] = 1;
    }

    for (let i = 0; i < n; i++) {
      const node = rig.nodes[i];
      this.parents[i] = node.parent;
      const p = i * POSE;
      this.restPose[p] = node.t[0]; this.restPose[p + 1] = node.t[1]; this.restPose[p + 2] = node.t[2];
      this.restPose[p + 3] = node.r[0]; this.restPose[p + 4] = node.r[1]; this.restPose[p + 5] = node.r[2]; this.restPose[p + 6] = node.r[3];
      this.restPose[p + 7] = node.s[0]; this.restPose[p + 8] = node.s[1]; this.restPose[p + 9] = node.s[2];
      // Rest local matrices, baked once — never-animated nodes keep these.
      this.bakeLocal(this.restPose, i);
    }
    composeWorlds(this.parents, this.locals, this.worlds);
  }

  /** Start a clip by name or index. Crossfades from the current clip over
   * `fade` seconds (0 = hard cut). Unknown names are ignored. */
  play(clip: string | number, opts: { loop?: boolean; fade?: number } = {}): void {
    const index = typeof clip === 'number' ? clip : this.anims.indexOf(clip);
    if (index < 0 || index >= this.rig.anims.length) return;
    const fade = opts.fade ?? 0.25;
    if (this.current && fade > 0) {
      this.previous = this.current;
      this.fadeTime = 0;
      this.fadeDuration = fade;
    } else {
      this.previous = null;
      this.fadeDuration = 0;
    }
    this.current = { index, time: 0, loop: opts.loop ?? true };
    this.time = 0;
    this.playing = true;
    this.done = false;
  }

  /** Advance by dt seconds and rebuild locals + worlds. Honours `playing`:
   * set it false to FREEZE the pose (walk → idle), true to resume. */
  update(dt: number): void {
    const cur = this.current;
    if (!cur || !this.playing) return;

    this.advance(cur, dt);
    this.time = cur.time;
    if (!cur.loop && this.time >= this.rig.anims[cur.index].duration) {
      this.done = true;
      this.playing = false;
    }

    this.evaluate(cur, this.poseA);

    let blend = 1; // weight of the CURRENT clip
    if (this.previous) {
      this.advance(this.previous, dt);
      this.fadeTime += dt;
      blend = this.fadeDuration > 0 ? Math.min(1, this.fadeTime / this.fadeDuration) : 1;
      if (blend >= 1) {
        this.previous = null;
      } else {
        this.evaluate(this.previous, this.poseB);
        this.blendPoses(this.poseB, this.poseA, blend, this.poseA);
      }
    }

    // Bake locals for animated nodes only — the rest keep their rest matrices.
    const n = this.rig.nodes.length;
    for (let i = 0; i < n; i++) {
      if (this.animated[i]) this.bakeLocal(this.poseA, i);
    }
    composeWorlds(this.parents, this.locals, this.worlds);
  }

  // ── internals ──────────────────────────────────────────────────────────────

  private advance(state: ClipState, dt: number): void {
    const duration = this.rig.anims[state.index].duration;
    state.time += dt;
    if (state.loop && duration > 0 && state.time >= duration) {
      state.time %= duration;
    } else if (!state.loop && state.time > duration) {
      state.time = duration;
    }
  }

  /** Write the clip's pose at its current time into `pose` (rest + channels). */
  private evaluate(state: ClipState, pose: Float32Array): void {
    pose.set(this.restPose);
    const anim = this.rig.anims[state.index];
    const s4 = this.sampleScratch;
    for (const ch of anim.channels) {
      sampleChannel(ch, state.time, s4);
      const p = ch.node * POSE;
      if (ch.path === 'translation') {
        pose[p] = s4[0]; pose[p + 1] = s4[1]; pose[p + 2] = s4[2];
      } else if (ch.path === 'rotation') {
        pose[p + 3] = s4[0]; pose[p + 4] = s4[1]; pose[p + 5] = s4[2]; pose[p + 6] = s4[3];
      } else {
        pose[p + 7] = s4[0]; pose[p + 8] = s4[1]; pose[p + 9] = s4[2];
      }
    }
  }

  /** out = mix(a, b, t) per node: lerp t/s, slerp r. out may alias b. */
  private blendPoses(a: Float32Array, b: Float32Array, t: number, out: Float32Array): void {
    const n = this.rig.nodes.length;
    for (let i = 0; i < n; i++) {
      const p = i * POSE;
      out[p] = a[p] + (b[p] - a[p]) * t;
      out[p + 1] = a[p + 1] + (b[p + 1] - a[p + 1]) * t;
      out[p + 2] = a[p + 2] + (b[p + 2] - a[p + 2]) * t;
      const q = quatSlerp(
        a[p + 3], a[p + 4], a[p + 5], a[p + 6],
        b[p + 3], b[p + 4], b[p + 5], b[p + 6],
        t,
      );
      out[p + 3] = q[0]; out[p + 4] = q[1]; out[p + 5] = q[2]; out[p + 6] = q[3];
      out[p + 7] = a[p + 7] + (b[p + 7] - a[p + 7]) * t;
      out[p + 8] = a[p + 8] + (b[p + 8] - a[p + 8]) * t;
      out[p + 9] = a[p + 9] + (b[p + 9] - a[p + 9]) * t;
    }
  }

  /** Bake pose[node] (TRS) into this.locals[node]. */
  private bakeLocal(pose: Float32Array, node: number): void {
    const p = node * POSE;
    const m = this.locals;
    const o = node * 16;
    const x = pose[p + 3], y = pose[p + 4], z = pose[p + 5], w = pose[p + 6];
    const x2 = x + x, y2 = y + y, z2 = z + z;
    const xx = x * x2, xy = x * y2, xz = x * z2;
    const yy = y * y2, yz = y * z2, zz = z * z2;
    const wx = w * x2, wy = w * y2, wz = w * z2;
    const sx = pose[p + 7], sy = pose[p + 8], sz = pose[p + 9];
    m[o] = (1 - (yy + zz)) * sx;
    m[o + 1] = (xy + wz) * sx;
    m[o + 2] = (xz - wy) * sx;
    m[o + 3] = 0;
    m[o + 4] = (xy - wz) * sy;
    m[o + 5] = (1 - (xx + zz)) * sy;
    m[o + 6] = (yz + wx) * sy;
    m[o + 7] = 0;
    m[o + 8] = (xz + wy) * sz;
    m[o + 9] = (yz - wx) * sz;
    m[o + 10] = (1 - (xx + yy)) * sz;
    m[o + 11] = 0;
    m[o + 12] = pose[p];
    m[o + 13] = pose[p + 1];
    m[o + 14] = pose[p + 2];
    m[o + 15] = 1;
  }
}
