// Minimal 3D math for the perspective layer: column-major mat4 (WebGPU NDC,
// depth 0..1, right-handed y-UP) + the two matrices a camera needs. Pure
// functions over Float32Array — headlessly tested.

export type Mat4 = Float32Array;
export interface V3 { x: number; y: number; z: number }

export function vec3(x = 0, y = 0, z = 0): V3 {
  return { x, y, z };
}

/** Perspective projection (fovY degrees, WebGPU depth range 0..1). */
export function mat4Perspective(fovYDeg: number, aspect: number, near: number, far: number): Mat4 {
  const f = 1 / Math.tan((fovYDeg * Math.PI) / 360);
  const m = new Float32Array(16);
  m[0] = f / Math.max(0.0001, aspect);
  m[5] = f;
  m[10] = far / (near - far);
  m[11] = -1;
  m[14] = (near * far) / (near - far);
  return m;
}

/** Orthographic projection (WebGPU depth 0..1) — shadow-map cameras. */
export function mat4Ortho(l: number, r: number, b: number, t: number, near: number, far: number): Mat4 {
  const m = new Float32Array(16);
  m[0] = 2 / (r - l);
  m[5] = 2 / (t - b);
  m[10] = 1 / (near - far);
  m[12] = (l + r) / (l - r);
  m[13] = (b + t) / (b - t);
  m[14] = near / (near - far);
  m[15] = 1;
  return m;
}

/** A view matrix looking from `eye` at `target` (y-up world). */
export function mat4LookAt(eye: V3, target: V3, up: V3 = vec3(0, 1, 0)): Mat4 {
  const fz = norm(sub(eye, target));          // camera forward = +z in view space
  const fx = norm(cross(up, fz));             // camera right
  const fy = cross(fz, fx);                   // camera up
  const m = new Float32Array(16);
  m[0] = fx.x; m[1] = fy.x; m[2] = fz.x;
  m[4] = fx.y; m[5] = fy.y; m[6] = fz.y;
  m[8] = fx.z; m[9] = fy.z; m[10] = fz.z;
  m[12] = -dot(fx, eye);
  m[13] = -dot(fy, eye);
  m[14] = -dot(fz, eye);
  m[15] = 1;
  return m;
}

/** m = a × b (column-major). */
export function mat4Mul(a: Mat4, b: Mat4): Mat4 {
  const m = new Float32Array(16);
  for (let c = 0; c < 4; c++) {
    for (let r = 0; r < 4; r++) {
      m[c * 4 + r] =
        a[r] * b[c * 4] + a[4 + r] * b[c * 4 + 1] + a[8 + r] * b[c * 4 + 2] + a[12 + r] * b[c * 4 + 3];
    }
  }
  return m;
}

/** Transform a point (w=1) and perspective-divide — for tests + picking. */
export function mat4Project(m: Mat4, p: V3): V3 {
  const x = m[0] * p.x + m[4] * p.y + m[8] * p.z + m[12];
  const y = m[1] * p.x + m[5] * p.y + m[9] * p.z + m[13];
  const z = m[2] * p.x + m[6] * p.y + m[10] * p.z + m[14];
  const w = m[3] * p.x + m[7] * p.y + m[11] * p.z + m[15] || 1;
  return { x: x / w, y: y / w, z: z / w };
}

/** General 4×4 inverse (column-major, cofactor expansion). Returns identity
 * for a singular input rather than NaNs — callers unproject with it and a
 * degenerate frame should read as "no transform", never as poison. */
export function mat4Inverse(m: Mat4): Mat4 {
  const inv = new Float32Array(16);
  inv[0] = m[5] * m[10] * m[15] - m[5] * m[11] * m[14] - m[9] * m[6] * m[15] + m[9] * m[7] * m[14] + m[13] * m[6] * m[11] - m[13] * m[7] * m[10];
  inv[4] = -m[4] * m[10] * m[15] + m[4] * m[11] * m[14] + m[8] * m[6] * m[15] - m[8] * m[7] * m[14] - m[12] * m[6] * m[11] + m[12] * m[7] * m[10];
  inv[8] = m[4] * m[9] * m[15] - m[4] * m[11] * m[13] - m[8] * m[5] * m[15] + m[8] * m[7] * m[13] + m[12] * m[5] * m[11] - m[12] * m[7] * m[9];
  inv[12] = -m[4] * m[9] * m[14] + m[4] * m[10] * m[13] + m[8] * m[5] * m[14] - m[8] * m[6] * m[13] - m[12] * m[5] * m[10] + m[12] * m[6] * m[9];
  inv[1] = -m[1] * m[10] * m[15] + m[1] * m[11] * m[14] + m[9] * m[2] * m[15] - m[9] * m[3] * m[14] - m[13] * m[2] * m[11] + m[13] * m[3] * m[10];
  inv[5] = m[0] * m[10] * m[15] - m[0] * m[11] * m[14] - m[8] * m[2] * m[15] + m[8] * m[3] * m[14] + m[12] * m[2] * m[11] - m[12] * m[3] * m[10];
  inv[9] = -m[0] * m[9] * m[15] + m[0] * m[11] * m[13] + m[8] * m[1] * m[15] - m[8] * m[3] * m[13] - m[12] * m[1] * m[11] + m[12] * m[3] * m[9];
  inv[13] = m[0] * m[9] * m[14] - m[0] * m[10] * m[13] - m[8] * m[1] * m[14] + m[8] * m[2] * m[13] + m[12] * m[1] * m[10] - m[12] * m[2] * m[9];
  inv[2] = m[1] * m[6] * m[15] - m[1] * m[7] * m[14] - m[5] * m[2] * m[15] + m[5] * m[3] * m[14] + m[13] * m[2] * m[7] - m[13] * m[3] * m[6];
  inv[6] = -m[0] * m[6] * m[15] + m[0] * m[7] * m[14] + m[4] * m[2] * m[15] - m[4] * m[3] * m[14] - m[12] * m[2] * m[7] + m[12] * m[3] * m[6];
  inv[10] = m[0] * m[5] * m[15] - m[0] * m[7] * m[13] - m[4] * m[1] * m[15] + m[4] * m[3] * m[13] + m[12] * m[1] * m[7] - m[12] * m[3] * m[5];
  inv[14] = -m[0] * m[5] * m[14] + m[0] * m[6] * m[13] + m[4] * m[1] * m[14] - m[4] * m[2] * m[13] - m[12] * m[1] * m[6] + m[12] * m[2] * m[5];
  inv[3] = -m[1] * m[6] * m[11] + m[1] * m[7] * m[10] + m[5] * m[2] * m[11] - m[5] * m[3] * m[10] - m[9] * m[2] * m[7] + m[9] * m[3] * m[6];
  inv[7] = m[0] * m[6] * m[11] - m[0] * m[7] * m[10] - m[4] * m[2] * m[11] + m[4] * m[3] * m[10] + m[8] * m[2] * m[7] - m[8] * m[3] * m[6];
  inv[11] = -m[0] * m[5] * m[11] + m[0] * m[7] * m[9] + m[4] * m[1] * m[11] - m[4] * m[3] * m[9] - m[8] * m[1] * m[7] + m[8] * m[3] * m[5];
  inv[15] = m[0] * m[5] * m[10] - m[0] * m[6] * m[9] - m[4] * m[1] * m[10] + m[4] * m[2] * m[9] + m[8] * m[1] * m[6] - m[8] * m[2] * m[5];
  const det = m[0] * inv[0] + m[1] * inv[4] + m[2] * inv[8] + m[3] * inv[12];
  if (!det || !Number.isFinite(det)) {
    const id = new Float32Array(16);
    id[0] = id[5] = id[10] = id[15] = 1;
    return id;
  }
  const k = 1 / det;
  for (let i = 0; i < 16; i++) inv[i] *= k;
  return inv;
}

/** The camera's right/up basis from a view matrix (billboards face with these). */
export function viewBasis(view: Mat4): { right: V3; up: V3 } {
  return {
    right: { x: view[0], y: view[4], z: view[8] },
    up: { x: view[1], y: view[5], z: view[9] },
  };
}

function sub(a: V3, b: V3): V3 {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z };
}
function cross(a: V3, b: V3): V3 {
  return { x: a.y * b.z - a.z * b.y, y: a.z * b.x - a.x * b.z, z: a.x * b.y - a.y * b.x };
}
function dot(a: V3, b: V3): number {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}
function norm(v: V3): V3 {
  const l = Math.hypot(v.x, v.y, v.z) || 1;
  return { x: v.x / l, y: v.y / l, z: v.z / l };
}

/**
 * Extract the six frustum planes of a column-major viewProj (WebGPU depth
 * 0..1; works for PERSPECTIVE and ORTHO alike): 24 floats, [a, b, c, d] ×
 * (left, right, bottom, top, near, far), xyz normalised. A point is inside
 * a plane when a·x + b·y + c·z + d ≥ 0. Gribb–Hartmann, near plane from
 * the z ≥ 0 clip (not GL's z ≥ -w).
 */
export function frustumPlanes(m: Mat4): Float32Array {
  const out = new Float32Array(24);
  // Row i of the column-major matrix: (m[i], m[4+i], m[8+i], m[12+i]).
  const set = (p: number, a: number, b: number, c: number, d: number): void => {
    const l = Math.hypot(a, b, c) || 1;
    out[p] = a / l; out[p + 1] = b / l; out[p + 2] = c / l; out[p + 3] = d / l;
  };
  const r = (i: number): [number, number, number, number] => [m[i], m[4 + i], m[8 + i], m[12 + i]];
  const [x0, y0, z0, w0] = r(0);
  const [x1, y1, z1, w1] = r(1);
  const [x2, y2, z2, w2] = r(2);
  const [x3, y3, z3, w3] = r(3);
  set(0, x3 + x0, y3 + y0, z3 + z0, w3 + w0);   // left   (x ≥ -w)
  set(4, x3 - x0, y3 - y0, z3 - z0, w3 - w0);   // right  (x ≤ +w)
  set(8, x3 + x1, y3 + y1, z3 + z1, w3 + w1);   // bottom
  set(12, x3 - x1, y3 - y1, z3 - z1, w3 - w1);  // top
  set(16, x2, y2, z2, w2);                      // near   (z ≥ 0)
  set(20, x3 - x2, y3 - y2, z3 - z2, w3 - w2);  // far    (z ≤ w)
  return out;
}

/** Sphere-vs-frustum: true when the sphere touches the volume (conservative
 * — corner cases may pass a sphere that is just outside; never culls a
 * visible one). `planes` from frustumPlanes(). */
export function sphereVsFrustum(planes: Float32Array, x: number, y: number, z: number, r: number): boolean {
  for (let p = 0; p < 24; p += 4) {
    if (planes[p] * x + planes[p + 1] * y + planes[p + 2] * z + planes[p + 3] < -r) return false;
  }
  return true;
}

/**
 * A world-space picking ray from an NDC point (nx, ny in -1..1, y UP) —
 * unproject near and far and take the difference. `invVp` is the inverse
 * of the camera's viewProj (mat4Inverse). Returns unit dir.
 */
export function rayFromNdc(invVp: Mat4, nx: number, ny: number): { origin: V3; dir: V3 } {
  const un = (z: number): V3 => {
    const x = invVp[0] * nx + invVp[4] * ny + invVp[8] * z + invVp[12];
    const y = invVp[1] * nx + invVp[5] * ny + invVp[9] * z + invVp[13];
    const zz = invVp[2] * nx + invVp[6] * ny + invVp[10] * z + invVp[14];
    const w = invVp[3] * nx + invVp[7] * ny + invVp[11] * z + invVp[15] || 1;
    return { x: x / w, y: y / w, z: zz / w };
  };
  const a = un(0);          // near plane (WebGPU depth 0)
  const b = un(0.999);      // toward far (not 1: w degenerates at infinity)
  const dir = norm(sub(b, a));
  return { origin: a, dir };
}

/** Ray vs sphere: nearest positive hit distance, or null. */
export function raySphere(origin: V3, dir: V3, c: V3, r: number): number | null {
  const oc = sub(origin, c);
  const b = dot(oc, dir);
  const disc = b * b - (dot(oc, oc) - r * r);
  if (disc < 0) return null;
  const s = Math.sqrt(disc);
  const t0 = -b - s, t1 = -b + s;
  if (t0 > 1e-6) return t0;
  if (t1 > 1e-6) return t1;   // origin inside the sphere
  return null;
}

/** Ray vs the horizontal plane y = h: hit point, or null (parallel/behind). */
export function rayPlaneY(origin: V3, dir: V3, h: number): V3 | null {
  if (Math.abs(dir.y) < 1e-9) return null;
  const t = (h - origin.y) / dir.y;
  if (t <= 1e-6) return null;
  return { x: origin.x + dir.x * t, y: h, z: origin.z + dir.z * t };
}

/**
 * Ray vs an ORIENTED box (the engine euler order: roll about z, pitch
 * about x, yaw about y — the mesh shader's rotate()): nearest positive hit
 * distance or null. Exact for boxes and a tight proxy for everything else —
 * bounding SPHERES are useless for flat meshes (a ground disc's sphere
 * swallows every click in the scene).
 */
export function rayObb(
  origin: V3, dir: V3, center: V3,
  half: V3, yaw: number, pitch: number, roll: number,
): number | null {
  // Transform the ray into the box's local frame: inverse rotation applied
  // in reverse order (yaw⁻¹, pitch⁻¹, roll⁻¹).
  const rot = (v: V3): V3 => {
    let { x, y, z } = v;
    // Inverse of the mesh shader's yaw rotate (right-hand-turn convention):
    // undo Ry(yaw) with cos(yaw)/sin(yaw) — NOT cos(−yaw) (see transform3d).
    const cy = Math.cos(yaw), sy = Math.sin(yaw);
    [x, z] = [x * cy + z * sy, -x * sy + z * cy];
    const cp = Math.cos(-pitch), sp = Math.sin(-pitch);
    [y, z] = [y * cp - z * sp, y * sp + z * cp];
    const cr = Math.cos(-roll), sr = Math.sin(-roll);
    [x, y] = [x * cr - y * sr, x * sr + y * cr];
    return { x, y, z };
  };
  const o = rot(sub(origin, center));
  const d = rot(dir);
  let tMin = -Infinity, tMax = Infinity;
  for (const [oc, dc, hc] of [[o.x, d.x, half.x], [o.y, d.y, half.y], [o.z, d.z, half.z]] as const) {
    if (Math.abs(dc) < 1e-12) {
      if (Math.abs(oc) > hc) return null;      // parallel and outside the slab
      continue;
    }
    const t1 = (-hc - oc) / dc, t2 = (hc - oc) / dc;
    tMin = Math.max(tMin, Math.min(t1, t2));
    tMax = Math.min(tMax, Math.max(t1, t2));
    if (tMin > tMax) return null;
  }
  if (tMax <= 1e-6) return null;               // box behind the ray
  return tMin > 1e-6 ? tMin : tMax;            // origin inside: exit distance
}

/**
 * Ray vs an oriented box derived from a mesh's LOCAL geometry AABB. `pos` +
 * `size` (w,h,d) + euler place a UNIT-fit geometry; `bounds` is that
 * geometry's local AABB (centre + half-extents, unit space). The box is the
 * AABB scaled by `size`, its centre offset rotated into world (mesh euler
 * order: roll·z → pitch·x → yaw·y). With no `bounds`, falls back to the
 * symmetric size/2 cube (only exact for `box`). Nearest positive t or null.
 *
 * This is what makes picking tight for off-centre / thin / multi-part model
 * geometry, whose symmetric w/h/d cube overshoots and swallows clicks behind
 * it.
 */
export function rayObbLocal(
  origin: V3, dir: V3, pos: V3, size: V3, yaw: number, pitch: number, roll: number,
  bounds?: { cx: number; cy: number; cz: number; hx: number; hy: number; hz: number },
): number | null {
  if (!bounds) {
    return rayObb(origin, dir, pos, { x: size.x / 2, y: size.y / 2, z: size.z / 2 }, yaw, pitch, roll);
  }
  let ox = bounds.cx * size.x, oy = bounds.cy * size.y, oz = bounds.cz * size.z;
  const cr = Math.cos(roll), sr = Math.sin(roll);
  [ox, oy] = [ox * cr - oy * sr, ox * sr + oy * cr];
  const cp = Math.cos(pitch), sp = Math.sin(pitch);
  [oy, oz] = [oy * cp - oz * sp, oy * sp + oz * cp];
  const cy = Math.cos(yaw), sy = Math.sin(yaw);
  // Forward yaw rotate — matches the mesh shader (right-hand-turn convention).
  [ox, oz] = [ox * cy - oz * sy, ox * sy + oz * cy];
  return rayObb(
    origin, dir, { x: pos.x + ox, y: pos.y + oy, z: pos.z + oz },
    { x: bounds.hx * size.x, y: bounds.hy * size.y, z: bounds.hz * size.z }, yaw, pitch, roll,
  );
}
